interface FramecnThemeContextValue {
  theme?: Partial<FramecnTheme>;
  mode?: "light" | "dark";
  baseColor?: BaseColorName;
  themeName?: ThemeName;
}

const FramecnThemeContext = createContext<FramecnThemeContextValue>({});

export interface FramecnUIProviderProps {
  theme?: Partial<FramecnTheme>;
  mode?: "light" | "dark";
  baseColor?: BaseColorName;
  themeName?: ThemeName;
  iconLibrary?: IconLibrary;
  children: ReactNode;
}

export const FramecnUIProvider = ({
  theme,
  mode,
  baseColor,
  themeName,
  iconLibrary = "lucide",
  children,
}: FramecnUIProviderProps) =>
  createElement(
    FramecnThemeContext.Provider,
    { value: { baseColor, mode, theme, themeName } },
    createElement(FramecnIconProvider, { library: iconLibrary }, children)
  );

export const useFramecnMode = (
  fallback: "light" | "dark" = "light"
): "light" | "dark" => useContext(FramecnThemeContext).mode ?? fallback;

export const resolveFramecnTheme = (
  mode: "light" | "dark",
  baseColor: BaseColorName = "neutral",
  themeName: ThemeName = baseColor
): FramecnTheme => ({
  ...(mode === "dark" ? defaultDarkTheme : defaultLightTheme),
  ...themePresets[baseColor][mode],
  ...themePresets[themeName][mode],
});

export const useFramecnTheme = (
  override?: Partial<FramecnTheme>,
  modeOverride?: "light" | "dark"
): FramecnTheme => {
  const ctx = useContext(FramecnThemeContext);
  const mode = ctx.mode ?? modeOverride ?? "light";
  const base = resolveFramecnTheme(mode, ctx.baseColor, ctx.themeName);
  return { ...base, ...ctx.theme, ...override };
};

"use client";

import { Timegroup, useTimingInfo } from "@editframe/react";
import { createContext, useContext, useMemo } from "react";
import type { CSSProperties, ReactNode } from "react";

export const DEFAULT_FPS = 30;

interface FrameContextValue {
  frame: number;
  fps: number;
}

const FrameContext = createContext<FrameContextValue>({
  fps: DEFAULT_FPS,
  frame: 0,
});

export const useCurrentFrame = (): number => useContext(FrameContext).frame;

export const useVideoConfig = (): { fps: number } => {
  const { fps } = useContext(FrameContext);
  return { fps };
};

export interface FrameProviderProps {
  children: ReactNode;
  durationMs: number;
  fps?: number;
  className?: string;
  style?: CSSProperties;
}

export const FrameProvider = ({
  children,
  durationMs,
  fps = DEFAULT_FPS,
  className,
  style,
}: FrameProviderProps) => {
  const { ref, ownCurrentTimeMs } = useTimingInfo();
  const frame = Math.round((ownCurrentTimeMs / 1000) * fps);
  const value = useMemo(() => ({ fps, frame }), [frame, fps]);

  return (
    <Timegroup
      ref={ref}
      className={className}
      duration={`${durationMs}ms`}
      mode="fixed"
      style={{
        height: "100%",
        inset: 0,
        position: "absolute",
        width: "100%",
        ...style,
      }}
    >
      <FrameContext.Provider value={value}>{children}</FrameContext.Provider>
    </Timegroup>
  );
};

import { clampChroma, converter, formatRgb, interpolate, parse } from "culori";
import type { Oklch, Rgb } from "culori";

// React bundlers replace NODE_ENV; this module does not require Node ambient types.
declare const process: { env: { NODE_ENV?: string } };

const toRgb = converter("rgb");
const toOklch = converter("oklch");

const BLACK: Rgb = { alpha: 1, b: 0, g: 0, mode: "rgb", r: 0 };

export const parseColor = (c: string): Rgb => {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[framecn-ui] parseColor cannot resolve CSS variable "${s}" under Editframe's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default."
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[framecn-ui] parseColor could not parse "${s}"; using black.`
      );
    }
    return { ...BLACK };
  }

  return { alpha: rgb.alpha ?? 1, b: rgb.b, g: rgb.g, mode: "rgb", r: rgb.r };
};

export const oklchToRgb = (l: number, c: number, h: number): Rgb => {
  const mapped = clampChroma({ c, h, l, mode: "oklch" }, "oklch", "rgb");
  return toRgb(mapped);
};

export const rgbToOklch = (rgb: Rgb): Oklch => {
  const { l, c, h } = toOklch(rgb);
  return { c, h: Number.isFinite(h) ? h : 0, l, mode: "oklch" };
};
const resolveColorString = (s: string): string => {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[framecn-ui] mixOklch cannot resolve CSS variable "${trimmed}" under Editframe's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default."
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `[framecn-ui] mixOklch could not parse "${trimmed}"; using black.`
      );
    }
    return "#000";
  }
  return trimmed;
};

export const toCss = (color: Rgb): string => formatRgb(color);

export const mixOklch = (a: string, b: string, t: number): string => {
  const mixed = clampChroma(
    interpolate([resolveColorString(a), resolveColorString(b)], "oklch")(t),
    "oklch",
    "rgb"
  );
  return toCss(toRgb(mixed));
};

import {
  useCurrentFrame,
  useVideoConfig,
} from "@/lib/framecn-ui/frame";

import type { Step } from "./types";

export const framesFor = (
  d: number | { seconds: number },
  fps: number
): number => (typeof d === "number" ? d : Math.round(d.seconds * fps));

export const revealCount = (
  localFrame: number,
  fps: number,
  len: number,
  cps: number
): number => {
  const over = (len / cps) * fps;
  if (over <= 0) {
    return len;
  }
  return Math.max(0, Math.min(len, Math.floor((localFrame / over) * len)));
};

export const clamp01 = (t: number): number => Math.max(0, Math.min(1, t));

export const revealedText = (full: string, count: number): string => {
  const c = Math.max(0, Math.min(full.length, Math.floor(count)));
  return full.slice(0, c);
};

export interface TypewriterOptions {
  cps?: number;
  speed?: number;
  startFrame?: number;
}

export interface TypewriterState {
  text: string;
  count: number;
  done: boolean;
  typing: boolean;
}

export const typewriterAt = (
  full: string,
  frame: number,
  fps: number,
  options: TypewriterOptions = {}
): TypewriterState => {
  const { cps = 20, speed = 1, startFrame = 0 } = options;
  const local = frame * speed - startFrame;
  const count = local <= 0 ? 0 : revealCount(local, fps, full.length, cps);
  return {
    count,
    done: count >= full.length,
    text: revealedText(full, count),
    typing: count > 0 && count < full.length,
  };
};

export const useTypewriter = (
  full: string,
  options: TypewriterOptions = {}
): TypewriterState => {
  const { cps = 20, speed = 1, startFrame = 0 } = options;
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const local = frame * speed - startFrame;
  const count = local <= 0 ? 0 : revealCount(local, fps, full.length, cps);
  return {
    count,
    done: count >= full.length,
    text: revealedText(full, count),
    typing: count > 0 && count < full.length,
  };
};

export const useCurrentState = <S extends string>(
  steps: Step<S>[],
  defaultState: S,
  speed = 1
): S => {
  const effectiveFrame = useCurrentFrame() * speed;
  let current = defaultState;
  let bestAt = -Infinity;
  for (const step of steps) {
    if (step.at <= effectiveFrame && step.at >= bestAt) {
      bestAt = step.at;
      current = step.state;
    }
  }
  return current;
};

export const useStateTransition = <S extends string>(
  steps: Step<S>[],
  defaultState: S,
  speed = 1,
  defaultDuration = 8
): { from: S; to: S; progress: number } => {
  const effectiveFrame = useCurrentFrame() * speed;
  const started = steps
    .map((step, index) => ({ index, step }))
    .toSorted((a, b) => a.step.at - b.step.at || a.index - b.index)
    .filter((entry) => entry.step.at <= effectiveFrame);
  if (started.length === 0) {
    return { from: defaultState, progress: 1, to: defaultState };
  }
  const to = started.at(-1)?.step;
  if (!to) {
    return { from: defaultState, progress: 1, to: defaultState };
  }
  const from = started.length >= 2 ? started.at(-2)?.step : null;
  const dur = to.duration ?? defaultDuration;
  const progress = dur > 0 ? clamp01((effectiveFrame - to.at) / dur) : 1;
  return { from: from ? from.state : defaultState, progress, to: to.state };
};
